#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct AdvancedPodcastRouting {
    pub microphone_ids: Vec<String>,
    pub cameras: Vec<PodcastCameraMicrophones>,
}
impl AdvancedPodcastRouting {
    pub fn validate(&self, camera_ids: &[String]) -> bool {
        let unique:HashSet<_>=self.microphone_ids.iter().collect();
        !unique.is_empty() && unique.len()<=4 && unique.len()==self.microphone_ids.len()
            && !self.microphone_ids.iter().any(|id| id.trim().is_empty())
            && self.cameras.len()==camera_ids.len()
            && self.cameras.iter().map(|c|&c.channel_id).collect::<HashSet<_>>().len()==camera_ids.len()
            && self.cameras.iter().all(|c| camera_ids.contains(&c.channel_id) && !c.microphone_ids.is_empty()
                && c.microphone_ids.iter().collect::<HashSet<_>>().len()==c.microphone_ids.len()
                && c.microphone_ids.iter().all(|id|self.microphone_ids.contains(id)))
            && self.microphone_ids.iter().all(|id|self.cameras.iter().any(|c|c.microphone_ids.contains(id)))
    }
}
